        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the improper handling of an uninitialized pointer in the `rtr_mgr_init` function. Specifically, if the `groups_len` was zero or if the mutex initialization failed, the function would jump to an error label before the `config->groups` pointer was initialized. This resulted in an attempt to free an uninitialized pointer, leading to undefined behavior or crashes.

        Commit message:
        rtr_mgr: fix uninitialized pointer read in rtr_mgr_init

This fixes a bug introduced by 7c6ba5ccf8791a954d31a094bddc9858c381df84. Due to the way cleanup on
error is handled an uninitialized pointer is passed to free if the
execution jumps to err before config->groups is initialized. This
can happen when group_len is zero or when pthread_mutex_init fails.

This commit fixes this by reordering the instructions and returning
early if group_len is zero, because config->groups cannot be initialized
before group_len is validated. The other approach, using different error
labels, would unnecessarily complicate error handling.

coverity id: 1434592  

        Patch:

 int rtr_mgr_init(struct rtr_mgr_config **config_out,
 		 struct rtr_mgr_group groups[],
 		 const unsigned int groups_len,
 		 const unsigned int refresh_interval,
 		 const unsigned int expire_interval,
 		 const unsigned int retry_interval,
 		 const pfx_update_fp update_fp,
 		 const spki_update_fp spki_update_fp,
 		 const rtr_mgr_status_fp status_fp,
 		 void *status_fp_data)
 {
 	int err_code = RTR_ERROR;
 	struct pfx_table *pfxt = NULL;
 	struct spki_table *spki_table = NULL;
 	struct rtr_mgr_config *config = NULL;
-
 	*config_out = NULL;
-	*config_out = config = malloc(sizeof(*config));
-	if (!config)
-		return RTR_ERROR;
-
-	if (pthread_mutex_init(&config->mutex, NULL) != 0) {
-		MGR_DBG1("Mutex initialization failed");
-		goto err;
-	}

 	if (groups_len == 0) {
 		MGR_DBG1("Error Empty rtr_mgr_group array");
-		goto err;
+		return RTR_ERROR;
 	}

+	*config_out = config = malloc(sizeof(*config));
+	if (!config)
+		return RTR_ERROR;
+
 	config->len = groups_len;
 	config->groups = malloc(groups_len * sizeof(*groups));
 	if (!config->groups)
 		goto err;
 	memcpy(config->groups, groups, groups_len * sizeof(*groups));

+	if (pthread_mutex_init(&config->mutex, NULL) != 0) {
+		MGR_DBG1("Mutex initialization failed");
+		goto err;
+	}
+
 	/* sort array in asc preference order */
 	qsort(config->groups, config->len,
 	      sizeof(struct rtr_mgr_group), &rtr_mgr_config_cmp);

 	for (unsigned int i = 0; i < config->len; i++) {
 		struct rtr_mgr_group cg = config->groups[i];

 		if (cg.sockets_len == 0) {
 			MGR_DBG1("Error Empty sockets array in socket group!");
 			goto err;
 		}
 		if (i > 0 &&
 		    config->groups[i - 1].preference == cg.preference) {
 			MGR_DBG1("Error Same preference for 2 socket groups!");
 			goto err;
 		}
 	}

 	pfxt = malloc(sizeof(*pfxt));
 	if (!pfxt)
 		goto err;
 	pfx_table_init(pfxt, update_fp);

 	spki_table = malloc(sizeof(*spki_table));
 	if (!spki_table)
 		goto err;
 	spki_table_init(spki_table, spki_update_fp);

 	for (unsigned int i = 0; i < config->len; i++) {
 		config->groups[i].status = RTR_MGR_CLOSED;
 		for (unsigned int j = 0;
 		     j < config->groups[i].sockets_len; j++) {
 			if (rtr_init(config->groups[i].sockets[j], NULL,
 				     pfxt, spki_table, refresh_interval,
 				     expire_interval, retry_interval,
 				     rtr_mgr_cb, config) != RTR_SUCCESS) {
 				err_code = RTR_INVALID_PARAM;
 				goto err;
 			}
 		}
 	}
 	config->status_fp_data = status_fp_data;
 	config->status_fp = status_fp;

 	if (!*config_out)
 		printf("xyxyx");

 	return RTR_SUCCESS;

 err:
 	if (spki_table)
 		spki_table_free(spki_table);
 	if (pfxt)
 		pfx_table_free(pfxt);
 	free(pfxt);
 	free(spki_table);

 	free(config->groups);
 	free(config);
 	config = NULL;
 	*config_out = NULL;
 	return err_code;
 }



